def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    bg = max(range(10), key=lambda c: sum(v == c for row in g for v in row))

    # Locate the full-width or full-height line of color 2.
    line = None
    for r in range(h):
        if all(g[r][c] == 2 for c in range(w)):
            line = ("h", r)
            break
    if line is None:
        for c in range(w):
            if all(g[r][c] == 2 for r in range(h)):
                line = ("v", c)
                break
    if line is None:
        return g

    points = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] != bg and g[r][c] != 2]
    if not points:
        return g

    orient, pos = line
    if orient == "h":
        lo, hi = min(r for r, c in points), max(r for r, c in points)
        if hi < pos:
            shift = pos - 1 - hi
            new_points = [(r + shift, c) for r, c in points]
            barrier = min(r for r, c in new_points) - 1
        else:
            shift = pos + 1 - lo
            new_points = [(r + shift, c) for r, c in points]
            barrier = max(r for r, c in new_points) + 1
        for r, c in points:
            g[r][c] = bg
        for r, c in new_points:
            g[r][c] = grid[next(rr for rr, cc in points if cc == c and rr + shift == r)][c] if False else 7
        # Restore the original object colors at their translated coordinates.
        for r, c in points:
            g[r + shift][c] = grid[r][c]
        if 0 <= barrier < h:
            g[barrier] = [8] * w
    else:
        lo, hi = min(c for r, c in points), max(c for r, c in points)
        if hi < pos:
            shift = pos - 1 - hi
            new_points = [(r, c + shift) for r, c in points]
            barrier = min(c for r, c in new_points) - 1
        else:
            shift = pos + 1 - lo
            new_points = [(r, c + shift) for r, c in points]
            barrier = max(c for r, c in new_points) + 1
        for r, c in points:
            g[r][c] = bg
        for r, c in points:
            g[r][c + shift] = grid[r][c]
        if 0 <= barrier < w:
            for r in range(h):
                g[r][barrier] = 8
    return g
